        "SK-II's Pitera (a yeast ferment filtrate) helped popularize fermented skincare outside Korea, while Korean brands built entire product lines around galactomyces and bifida ferment lysate, often marketed for radiance and texture refinement.",
        "Fermented ingredients are generally well tolerated, but 'fermented' is not automatically synonymous with 'gentle' — as with any ingredient, patch testing is worthwhile for anyone with reactive or allergy-prone skin.",
