        "کاتێک چڕی دادەبەزێتە ژێر ١ سەد، براند بەگشتی ڕێگەیان پێدراوە ئەو پێکهاتانە بە هەر ڕیزبەندییەک لیبڵ بکەن، کە یەکێکە لە هۆکارەکانی ئەوەی چالاکەرێکی دیاریکراو کە بەدوایدا دەگەڕێیت لەوانەیە لە خوارتری لیستدا دەربکەوێت تەنانەت ئەگەر بە ڕێژەیەکی کاریگەر بوونی هەبێت — چڕی لەژێر ئاستی ١٪ ئاماژە پێنادرێت تەنها بە شوێنی لیستدا.",
