export function getArticleBySlug(slug) {
  return BEAUTY_ARTICLES.find((a) => a.slug === slug || a.id === slug) || null;
}

export function getArticlesByCategory(categoryId) {
  if (!categoryId || categoryId === "all") return BEAUTY_ARTICLES;
  return BEAUTY_ARTICLES.filter((a) => a.category === categoryId);
}

export function getFeaturedArticles() {
  return BEAUTY_ARTICLES.filter((a) => a.isFeatured);
}

export function getTrendingArticles() {
  return BEAUTY_ARTICLES.filter((a) => a.isTrending);
}

export function getEditorPicks() {
  return BEAUTY_ARTICLES.filter((a) => a.isEditorPick);
}

export function getShortReads() {
  return BEAUTY_ARTICLES.filter((a) => a.isShortRead || a.readingTime <= 4);
}

export function getDeepGuides() {
  return BEAUTY_ARTICLES.filter((a) => a.isDeepGuide || a.readingTime >= 7);
}

export function getIngredientSpotlight() {
  return BEAUTY_ARTICLES.filter((a) => a.category === "ingredients");
}

export function getProductDeepDives() {
  return BEAUTY_ARTICLES.filter((a) => a.category === "product-guides" || a.category === "french-pharmacy");
}

export function getHairAndScalp() {
  return BEAUTY_ARTICLES.filter((a) => a.category === "haircare" || a.category === "scalp-care");
}

export function getMakeupInspiration() {
  return BEAUTY_ARTICLES.filter((a) => a.category === "makeup" || a.category === "lip-care");
}
